	// presence
	bool hasAnySet() const noexcept {
		if (m_presence != 0) { return true; }
		if (m_Instrument.hasAnySet()) { return true; }
		if (m_Parties.hasAnySet()) { return true; }
		if (!m_NoOrdersGroup.empty()) { return true; }
		if (!m_NoExecsGroup.empty()) { return true; }
		if (!m_NoAllocsGroup.empty()) { return true; }
		return false;
	}
	bool hasAllocID() const noexcept { return (m_presence & (1ULL << P_AllocID)) != 0; }
	bool hasAllocTransType() const noexcept { return (m_presence & (1ULL << P_AllocTransType)) != 0; }
